const GUIDELINES: readonly ShowcaseGuideline[] = [
	{
		title: "One primary action per screen",
		do: {
			text: "Give the screen one default (solid) button for the action it exists for, and make the alternatives `outline` or `secondary`.",
			file: "button-do-1",
			source:
				'import * as React from "react";\nimport { Button } from "@workspace/ui/components/button";\n\nexport function ButtonDo1Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="flex gap-2">\n\t\t\t<Button variant="outline">Cancel</Button>\n\t\t\t<Button>Save</Button>\n\t\t</div>\n\t);\n}\n',
			render: (): React.JSX.Element => <Guideline1 />,
		},
		dont: {
			text: "Don't set two solid buttons side by side: neither reads as the main action, and Cancel looks as safe to press as Save.",
			file: "button-dont-1",
			source:
				'import * as React from "react";\nimport { Button } from "@workspace/ui/components/button";\n\nexport function ButtonDont1Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="flex gap-2">\n\t\t\t<Button>Cancel</Button>\n\t\t\t<Button>Save</Button>\n\t\t</div>\n\t);\n}\n',
			render: (): React.JSX.Element => <Guideline2 />,
		},
	},
	{
		title: "Say what the action does",
		do: {
			text: 'Label a button with the verb and its object ("Save changes"), so it makes sense on its own and to a screen reader.',
			file: "button-do-2",
			source:
				'import * as React from "react";\nimport { Button } from "@workspace/ui/components/button";\n\nexport function ButtonDo2Example(): React.JSX.Element {\n\treturn <Button>Save changes</Button>;\n}\n',
			render: (): React.JSX.Element => <Guideline3 />,
		},
		dont: {
			text: 'Don\'t use a vague word ("OK", "Click here"): people have to read around the button to learn what it does.',
			file: "button-dont-2",
			source:
				'import * as React from "react";\nimport { Button } from "@workspace/ui/components/button";\n\nexport function ButtonDont2Example(): React.JSX.Element {\n\treturn <Button>OK</Button>;\n}\n',
			render: (): React.JSX.Element => <Guideline4 />,
		},
	},
	{
		title: "Keep red for what cannot be undone",
		do: {
			text: "Use `destructive` for an action that deletes or cannot be undone, with a glyph that says so.",
			file: "button-do-3",
			source:
				'import * as React from "react";\nimport { Button } from "@workspace/ui/components/button";\nimport { Trash2Icon } from "lucide-react";\n\nexport function ButtonDo3Example(): React.JSX.Element {\n\treturn (\n\t\t<Button variant="destructive">\n\t\t\t<Trash2Icon aria-hidden="true" />\n\t\t\tDelete project\n\t\t</Button>\n\t);\n}\n',
			render: (): React.JSX.Element => <Guideline5 />,
		},
		dont: {
			text: "Don't paint a safe action red: people learn to ignore the colour, and miss it when it matters.",
			file: "button-dont-3",
			source:
				'import * as React from "react";\nimport { Button } from "@workspace/ui/components/button";\n\nexport function ButtonDont3Example(): React.JSX.Element {\n\treturn <Button variant="destructive">Export report</Button>;\n}\n',
			render: (): React.JSX.Element => <Guideline6 />,
		},
	},
	{
		title: "Show the wait in the button",
		do: {
			text: "Pass `loading` while the action runs: the spinner sits in the button, clicks are blocked and the wait is announced.",
			file: "button-do-4",
			source:
				'import * as React from "react";\nimport { Button } from "@workspace/ui/components/button";\n\nexport function ButtonDo4Example(): React.JSX.Element {\n\treturn <Button loading>Saving…</Button>;\n}\n',
			render: (): React.JSX.Element => <Guideline7 />,
		},
		dont: {
			text: "Don't put a spinner beside a button that still takes clicks: a second click sends the action twice.",
			file: "button-dont-4",
			source:
				'import * as React from "react";\nimport { Button } from "@workspace/ui/components/button";\nimport { Spinner } from "@workspace/ui/components/spinner";\n\nexport function ButtonDont4Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="flex items-center gap-2">\n\t\t\t<Button>Save</Button>\n\t\t\t<Spinner aria-label="Saving" />\n\t\t</div>\n\t);\n}\n',
			render: (): React.JSX.Element => <Guideline8 />,
		},
	},
];

export function ButtonFeatures(): React.JSX.Element {
	return <ShowcaseFeatureList features={FEATURES} guidelines={GUIDELINES} />;
}
